<?php
namespace Modules\Ran\Http\Controllers;
use Illuminate\Http\Request;use Modules\Ran\Entities\{Item,StockLot,StockMovement};use Modules\Ran\Http\Requests\StockReceiptRequest;use Modules\Ran\Services\InventoryService;
class InventoryController extends RanController {public function index(Request $request){$q=StockLot::with('item')->forLocation($request->integer('location_id')?:null)->forStore($request->integer('store_id')?:null);if($request->filled('status'))$q->where('stock_status',$request->status);if($request->filled('search'))$q->where(function($x)use($request){$s='%'.$request->search.'%';$x->where('lot_no','like',$s)->orWhere('serial_no','like',$s)->orWhereHas('item',fn($i)=>$i->where('name','like',$s)->orWhere('sku','like',$s));});return view('ran::inventory.index',array_merge($this->pageOptions(),['lots'=>$q->latest('id')->paginate(25)->withQueryString()]));} public function movements(Request $request){$q=StockMovement::with(['item','stockLot'])->forLocation($request->integer('location_id')?:null)->forStore($request->integer('store_id')?:null);return view('ran::inventory.movements',array_merge($this->pageOptions(),['movements'=>$q->latest('movement_at')->paginate(30)->withQueryString()]));} public function createReceipt(){return view('ran::inventory.receive',array_merge($this->pageOptions(),['items'=>Item::where('is_active',1)->pluck('name','id')]));} public function storeReceipt(StockReceiptRequest $request,InventoryService $service){$service->receive($request->validated());return $this->success('Stock received successfully.','ran.inventory.index');} public function createAdjustment(StockLot $lot){return view('ran::inventory.adjust',array_merge($this->pageOptions(),compact('lot')));} public function storeAdjustment(Request $request,StockLot $lot,InventoryService $service){$data=$request->validate(['quantity_variance'=>'required|numeric','weight_variance'=>'required|numeric','reason'=>'required|string|max:1000']);$service->adjust($lot,(float)$data['quantity_variance'],(float)$data['weight_variance'],$data['reason']);return $this->success('Stock adjustment posted.','ran.inventory.index');}}
